type ValuesEditor interface {
	AppendValues(xs ...bob.Expression)
	RowCount() int
	SetValue(row, col int, x bob.Expression)
	AppendOrder(x bob.Expression)
	ClearOrderBy()
	SetLimit(x any)
	SetOffset(x any)
	SetFetch(x clause.Fetch)
}

type valuesEditor struct {
	q         *valuesState
	ownedRows bool
}

func (s *valuesState) open() *valuesEditor {
	s.RowVals = slices.Clip(s.RowVals)
	s.OrderBy.Expressions = slices.Clip(s.OrderBy.Expressions)

	return &valuesEditor{q: s}
}

func (e *valuesEditor) close() {
	e.q = nil
}

func (s *valuesState) apply(ms []bob.Mod[ValuesEditor]) {
	if len(ms) == 0 {
		return
	}
	e := s.open()
	defer e.close()
	bob.Mods[ValuesEditor](ms).Edit(e)
}

func (s valuesState) WithMods(ms []bob.Mod[ValuesEditor]) bob.QuerySource[ValuesEditor] {
	s.apply(ms)
	return &s
}

func NewValuesSource(ms ...bob.Mod[ValuesEditor]) bob.QuerySource[ValuesEditor] {
	s := new(valuesState)
	s.apply(ms)
	return s
}

func NewValues(
	hooks []bob.QueryHook[ValuesEditor],
	ms ...bob.Mod[ValuesEditor],
) bob.QueryBuilder[ValuesEditor] {
	return bob.NewQueryBuilder(NewValuesSource(ms...), Dialect, bob.QueryTypeValues, hooks...)
}

func (e *valuesEditor) AppendValues(xs ...bob.Expression) {
	e.q.AppendValues(xs...)
}

func (e *valuesEditor) RowCount() int {
	return len(e.q.RowVals)
}

func (e *valuesEditor) SetValue(row, col int, x bob.Expression) {
	if !e.ownedRows {
		e.q.RowVals = internal.CloneRows(e.q.RowVals)
		e.ownedRows = true
	}
	e.q.RowVals[row][col] = x
}

func (e *valuesEditor) AppendOrder(x bob.Expression) {
	e.q.AppendOrder(x)
}

func (e *valuesEditor) ClearOrderBy() {
	e.q.ClearOrderBy()
}

func (e *valuesEditor) SetLimit(x any) {
	e.q.SetLimit(x)
}

func (e *valuesEditor) SetOffset(x any) {
	e.q.SetOffset(x)
}

func (e *valuesEditor) SetFetch(x clause.Fetch) {
	e.q.SetFetch(x)
}

type MergeEditor interface {
	AppendCTE(x bob.Expression)
	SetRecursive(v bool)
	SetTarget(ref clause.TableRef)
	SetTargetName(x any)
	SetTargetAlias(alias string)
	SetOnly(v bool)
	SetUsing(x MergeUsing)
	SetUsingOnly(v bool)
	SetUsingSource(x any)
	SetUsingCondition(x bob.Expression)
	AppendWhen(x MergeWhen)
	AppendReturning(xs ...any)
	SetReturning(xs ...any)
	HasReturning() bool
	SetOldAlias(v string)
	SetNewAlias(v string)
	AppendHooks(fs ...func(context.Context, bob.Executor) (context.Context, error))
	SetHooks(fs ...func(context.Context, bob.Executor) (context.Context, error))
	AppendLoader(fs ...bob.Loader)
	SetLoaders(fs ...bob.Loader)
	AppendMapperMod(f scan.MapperMod)
	SetMapperMods(fs ...scan.MapperMod)
	NextUniqueInt() uint64
	AppendContextualMod(ms ...bob.ContextualMod[MergeEditor])
	AppendContextualModFunc(f func(context.Context, MergeEditor) (context.Context, error))
}

type mergeEditor struct {
	q *mergeState
}

func (s *mergeState) open() *mergeEditor {
	s.CTEs = slices.Clip(s.CTEs)
	s.When = slices.Clip(s.When)
	s.Returning.Expressions = slices.Clip(s.Returning.Expressions)
	s.Mods = slices.Clip(s.Mods)
	s.Hooks = slices.Clip(s.Hooks)
	s.Load.Clip()
	return &mergeEditor{q: s}
}

func (e *mergeEditor) close() {
	e.q = nil
}

func (s *mergeState) apply(ms []bob.Mod[MergeEditor]) {
	if len(ms) == 0 {
		return
	}
	e := s.open()
	defer e.close()
	bob.Mods[MergeEditor](ms).Edit(e)
}

func (s mergeState) WithMods(ms []bob.Mod[MergeEditor]) bob.QuerySource[MergeEditor] {
	s.apply(ms)
	return &s
}

func NewMergeSource(ms ...bob.Mod[MergeEditor]) bob.QuerySource[MergeEditor] {
	s := new(mergeState)
	s.apply(ms)
	return s
}

func NewMerge(
	hooks []bob.QueryHook[MergeEditor],
	ms ...bob.Mod[MergeEditor],
) bob.QueryBuilder[MergeEditor] {
	return bob.NewQueryBuilder(NewMergeSource(ms...), Dialect, bob.QueryTypeMerge, hooks...)
}

func (s *mergeState) resolveMods(ctx context.Context) (context.Context, error) {
	e := s.open()
	defer e.close()
	return s.RunContextualMods(ctx, e)
}

